function hasPairSum(root: TreeNode | null, k: number): boolean {
  const seen = new Set<number>();
  const stack: (TreeNode | null)[] = [root];
  while (stack.length) {
    const node = stack.pop();
    if (!node) continue;
    if (seen.has(k - node.val)) return true;
    seen.add(node.val);
    stack.push(node.left, node.right);
  }
  return false;
}

