function hasPairSum(root: TreeNode | null, k: number): boolean {
  const vals: number[] = [];
  const stack: TreeNode[] = [];
  let cur = root;
  while (cur || stack.length) {
    while (cur) { stack.push(cur); cur = cur.left; }
    const node = stack.pop()!;
    vals.push(node.val);
    cur = node.right;
  }
  let lo = 0, hi = vals.length - 1;
  while (lo < hi) {
    const s = vals[lo] + vals[hi];
    if (s === k) return true;
    if (s < k) lo++;
    else hi--;
  }
  return false;
}

